export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9A-Fa-f]$/.test(c)

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const lines = new Array(n + 1)
  const cols = new Array(n + 1)
  let l = 1
  let c = 1
  for (let i = 0; i < n; i++) {
    lines[i] = l
    cols[i] = c
    if (cs[i] === '\n') {
      l++
      c = 1
    } else if (cs[i] === '\t') c = (Math.floor((c - 1) / 4) + 1) * 4 + 1
    else c++
  }
  lines[n] = l
  cols[n] = c
  const err = (i, reason) => new ScanError(lines[i], cols[i], reason)
  const tokens = []
  const push = (i, kind, body) => tokens.push({ line: lines[i], col: cols[i], kind, body })

  let i = 0
  while (i < n) {
    const ch = cs[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
      i++
      continue
    }
    if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cs[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') {
          depth++
          i += 2
        } else if (cs[i] === '*' && cs[i + 1] === '/') {
          depth--
          i += 2
        } else i++
      }
      if (depth > 0) throw err(start, 'unterminated block comment')
      continue
    }
    if (ch === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) throw err(i, 'unterminated string')
      push(i, 'rawstring', JSON.stringify(cs.slice(i + 2, j).join('')))
      i = j + 1
      continue
    }
    if (isIdStart(ch)) {
      let j = i + 1
      while (j < n && isIdPart(cs[j])) j++
      const w = cs.slice(i, j).join('')
      push(i, KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      i = j
      continue
    }
    if (isDigit(ch)) {
      let j = i
      const run = (pred) => {
        // digits with single underscores between digits
        if (!pred(cs[j])) return false
        j++
        for (;;) {
          if (pred(cs[j])) j++
          else if (cs[j] === '_' && pred(cs[j + 1])) j += 2
          else break
        }
        return true
      }
      let ok = true
      const p = cs[i + 1]
      if (ch === '0' && p !== undefined && /^[xXbBoO]$/.test(p)) {
        const lp = p.toLowerCase()
        const pred = lp === 'x' ? isHex : lp === 'b' ? (d) => d === '0' || d === '1' : (d) => d >= '0' && d <= '7' && d.length === 1
        j = i + 2
        ok = run(pred)
      } else {
        run(isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) {
          j++
          run(isDigit)
        }
        if (cs[j] === 'e' || cs[j] === 'E') {
          if (isDigit(cs[j + 1])) {
            j++
            run(isDigit)
          } else if ((cs[j + 1] === '+' || cs[j + 1] === '-') && isDigit(cs[j + 2])) {
            j += 2
            run(isDigit)
          }
        }
      }
      if (!ok || isIdPart(cs[j])) {
        while (j < n && isIdPart(cs[j])) j++
        throw err(i, `invalid number ${cs.slice(i, j).join('')}`)
      }
      push(i, 'number', cs.slice(i, j).join(''))
      i = j
      continue
    }
    if (ch === '"') {
      let j = i + 1
      let out = ''
      for (;;) {
        if (j >= n) throw err(i, 'unterminated string')
        const d = cs[j]
        if (d === '"') {
          j++
          break
        }
        if (d === '\n') throw err(j, 'newline in string')
        if (d !== '\\') {
          out += d
          j++
          continue
        }
        const e = cs[j + 1]
        if (e === undefined) throw err(i, 'unterminated string')
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) {
          out += simple[e]
          j += 2
        } else if (e === 'x') {
          let k = j + 2
          for (; k < j + 4; k++) {
            if (k >= n) throw err(i, 'unterminated string')
            if (!isHex(cs[k])) throw err(j, 'invalid escape \\x')
          }
          out += String.fromCodePoint(parseInt(cs[j + 2] + cs[j + 3], 16))
          j += 4
        } else if (e === 'u') {
          if (j + 2 >= n) throw err(i, 'unterminated string')
          if (cs[j + 2] !== '{') throw err(j, 'invalid escape \\u')
          let k = j + 3
          let v = 0
          let cnt = 0
          for (;;) {
            if (k >= n) throw err(i, 'unterminated string')
            if (isHex(cs[k])) {
              v = v * 16 + parseInt(cs[k], 16)
              cnt++
              if (v > 0x10ffff) throw err(j, 'invalid escape \\u')
              k++
            } else if (cs[k] === '}' && cnt > 0) {
              k++
              break
            } else throw err(j, 'invalid escape \\u')
          }
          out += String.fromCodePoint(v)
          j = k
        } else throw err(j, `invalid escape \\${e}`)
      }
      push(i, 'string', JSON.stringify(out))
      i = j
      continue
    }
    const two = ch + (cs[i + 1] ?? '')
    if (PUNCT2.has(two)) {
      push(i, 'punct', two)
      i += 2
      continue
    }
    if (PUNCT1.has(ch)) {
      push(i, 'punct', ch)
      i++
      continue
    }
    throw err(i, `unexpected character ${ch}`)
  }
  return tokens
}
